% STATUS: SCRATCH -- 2026-11-02 (user): independent benchmark for 0-12 s, no filter. Information on an angle per step from the thermal displacement alone: I = (a_11 - a_33)^2 / (c a_11 a_33), c = 1 (variance estimate of the off-diagonal element, sigma(a_uw) = sqrt(a_11 a_33 / N)) and c = 2.5 (10-21 memory). sigma(t) = 1 / sqrt(1 / P0 + sum I), P0 = (10 deg)^2. Against the measured rms per axis, gate on, off_slope off and on, temp_off_slope.mat, 20 seeds. Truth: true gains of the fillet floor run, temp_hold_angle12.mat seed 1. No figure beyond MATLAB window 29.
%   Sanity: at 10 s the bound is near the measured 4 deg. Output fig_1102_info_bound.png
fo = fullfile(fileparts(fileparts(fileparts(mfilename('fullpath')))), 'test_results', 'temp_3d_wsonly');  H = load(fullfile(fo, 'temp_hold_angle12.mat'));  r = H.rs{1};  n = find(isfinite(r.aT_tr) & isfinite(r.aN_tr), 1, 'last');  t = r.t(1:n);  a1 = r.aT_tr(1:n);  a3 = r.aN_tr(1:n);  I0 = (a1 - a3).^2 ./ (a1 .* a3);
S = load(fullfile(fo, 'temp_off_slope.mat'));  rm = cell(2, 1);  for a = 1:2; id = find(S.IA == a);  X = cell2mat(cellfun(@(q) q.thx(1:n), S.rs(id)', 'UniformOutput', false));  Y = cell2mat(cellfun(@(q) q.thy(1:n), S.rs(id)', 'UniformOutput', false));  rm{a} = sqrt(mean((X.^2 + Y.^2) / 2, 2)); end
sg = @(c) 1 ./ sqrt(1 / (10 * pi / 180)^2 + cumsum(I0 / c)) * 180 / pi;  s1 = sg(1);  s2 = sg(2.5);
fprintf(' t s | a_11 a_33 | I per step | bound c=1, c=2.5 deg | measured off_slope off, on deg\n');
for x = [1 5 10 10.25 10.5 10.75 11 11.25 11.5 12]; i = find(t >= x - 1e-6, 1);  if isempty(i); i = n; end;  fprintf('%5.2f | %.3f %.3f | %.2e | %.2f %.2f | %.2f %.2f\n', t(i), a1(i), a3(i), I0(i), s1(i), s2(i), rm{1}(i), rm{2}(i)); end
if any(findall(0, 'Type', 'figure') == 29); close(29); end
f = figure(29);  set(f, 'Color', 'w', 'Position', [80 80 1300 620], 'Visible', 'on', 'Name', 'angle error against the information bound');  a = axes(f);  hold(a, 'on');  k = (1:3:n)';  h1 = plot(a, t(k), movmean(rm{1}(k), 15), 'Color', [0.85 0 0], 'LineWidth', 1.6);  h2 = plot(a, t(k), movmean(rm{2}(k), 15), 'Color', [0 0.6 0.2], 'LineWidth', 1.6);  h3 = plot(a, t(k), s1(k), 'k--', 'LineWidth', 1.3);  h4 = plot(a, t(k), s2(k), 'k:', 'LineWidth', 1.3);  set(a, 'YScale', 'log', 'FontSize', 14, 'FontWeight', 'bold', 'LineWidth', 1.2);  xlim(a, [1 12]);  ylim(a, [0.2 12]);  xline(a, 10, 'k:', 'HandleVisibility', 'off');  xline(a, 11, 'k:', 'HandleVisibility', 'off');  box(a, 'on');  xlabel(a, 'Time (sec)');  ylabel(a, 'angle error, per axis  [deg]');  legend(a, [h1 h2 h3 h4], {'measured, current', 'measured, off slope term', 'bound, c = 1', 'bound, c = 2.5'}, 'Location', 'northoutside', 'Orientation', 'horizontal');
exportgraphics(f, fullfile(fo, 'fig_1102_info_bound.png'), 'Resolution', 130);
